# Tutorial 00 · Celda 51
# Preparación y ejemplo originales (autónomos)

import aed_utilities as aed

class Nodoi:
  def __init__(self, izq, info, der):
    self.izq=izq
    self.info=info
    self.der=der
  def postorden(self):
    self.izq.postorden()
    self.der.postorden()
    print(self.info, end=" ")

class Nodoe:
  def __init__(self, info=""):
    self.info=info
  def postorden(self):
    print(self.info, end=" ")

class Arbol:
  def __init__(self,raiz=Nodoe()):
    self.raiz=raiz

  def postorden(self):
    print("Postorden:", end=" ")
    self.raiz.postorden()
    print()

formula= Arbol(
            Nodoi(
                Nodoi(Nodoe("a"),"+",Nodoe("1")),
                "*",
                Nodoi(
                    Nodoe("2"),
                    "-",
                    Nodoi(Nodoe("1"),"/",Nodoe("b"))
                )
            )
        )

formula.postorden()

# Dibujo del tutorial · celda 51
btd = aed.BinaryTreeDrawer(fieldData="info", fieldLeft="izq", fieldRight="der", classNone=Nodoe)
btd.draw_tree(formula, "raiz")
